"""Account-scoped training state and propagation of task changes to configuration."""
from collections.abc import Callable
from dataclasses import dataclass
import json
import time
from typing import Any, Protocol

Record = dict[str, Any]


def clear_training_private_state(training: dict[str, Any], reason: str) -> dict[str, Any]:
    training["preview_urls"] = []
    training["previews"] = []
    training["preview_cache_key"] = None
    training["preview_sprite_versions"] = {}
    training["last_preview_id"] = ""
    training["approved_preview_id"] = ""
    training["active_training_task_id"] = ""
    training["preview_stale_reason"] = reason
    return training


class TrainingStateVisibility(Protocol):
    def __call__(self, record: Record, user: Record, target_user_id: str | None = None) -> bool: ...


@dataclass(frozen=True)
class TrainingStateAccess:
    owner: Callable[[Record | None], str]
    visible: TrainingStateVisibility
    admin: Callable[[Record], bool]
    current_owner: Callable[[], Record]


@dataclass(frozen=True)
class TrainingStateStorage:
    find: Callable[[str], Record | None]
    load: Callable[[], Record]
    save: Callable[[Record], None]


class TrainingUserState:
    def __init__(self, defaults: Callable[[], Record], legacy_owner: Callable[[], str],
                 access: TrainingStateAccess, storage: TrainingStateStorage, sync_pipeline: Callable[[Record], None]):
        self.defaults, self.legacy_owner, self.access = defaults, legacy_owner, access
        self.storage, self.sync_pipeline = storage, sync_pipeline

    def default_training_state(self) -> dict[str, Any]:
        return json.loads(json.dumps(self.defaults()))

    def normalize_training_owner_key(self, owner_user_id: Any) -> str:
        owner = str(owner_user_id or "").strip()
        return owner or self.legacy_owner()

    def training_state_store(self, config: dict[str, Any]) -> dict[str, dict[str, Any]]:
        raw_store = config.get("training_by_user_id") if isinstance(config.get("training_by_user_id"), dict) else {}
        store: dict[str, dict[str, Any]] = {
            self.normalize_training_owner_key(owner): state
            for owner, state in raw_store.items()
            if isinstance(state, dict)
        }
        legacy_training = config.get("training") if isinstance(config.get("training"), dict) else None
        if legacy_training:
            owner = self.normalize_training_owner_key(self.access.owner(legacy_training))
            store.setdefault(owner, legacy_training)
        config["training_by_user_id"] = store
        return store

    def sanitize_training_state_for_user(self,
        training: dict[str, Any] | None,
        user: dict[str, Any],
        selected_ids: set[str],
        target_user_id: str | None = None,
    ) -> dict[str, Any]:
        if not isinstance(training, dict):
            return self.default_training_state()
        if not self.access.visible(training, user, target_user_id):
            return self.default_training_state()
        scoped_training = training
        raw_selected = [str(item) for item in scoped_training.get("selected_accessory_ids", []) if str(item)]
        if raw_selected:
            visible_selected = [item_id for item_id in raw_selected if item_id in selected_ids]
            if len(visible_selected) != len(raw_selected):
                scoped_training["selected_accessory_ids"] = visible_selected
                clear_training_private_state(scoped_training, "training_selection_not_visible")
        return scoped_training

    def training_state_for_user(self,
        config: dict[str, Any],
        user: dict[str, Any],
        selected_ids: set[str],
        target_user_id: str | None = None,
    ) -> dict[str, Any]:
        store = self.training_state_store(config)
        if self.access.admin(user) and target_user_id:
            owner_key = self.normalize_training_owner_key(target_user_id)
        elif self.access.admin(user):
            states = [
                self.sanitize_training_state_for_user(dict(state), user, selected_ids, None)
                for state in store.values()
                if isinstance(state, dict) and self.access.visible(state, user)
            ]
            aggregate = self.default_training_state()
            aggregate["training_states"] = states
            return aggregate
        else:
            owner_key = self.normalize_training_owner_key(user["id"])
        state = store.get(owner_key)
        return self.sanitize_training_state_for_user(dict(state) if isinstance(state, dict) else None, user, selected_ids, target_user_id)

    def set_training_state_for_user(self, config: dict[str, Any], user: dict[str, Any], training_state: dict[str, Any]) -> None:
        state = {**self.default_training_state(), **training_state, **self.access.current_owner()}
        owner_key = self.normalize_training_owner_key(state.get("owner_user_id") or user["id"])
        store = self.training_state_store(config)
        store[owner_key] = state
        config["training_by_user_id"] = store
        if self.access.admin(user):
            config["training"] = state

    def sync_training_state_from_task(self, job_id: str) -> None:
        task = self.storage.find(job_id)
        if not task:
            return
        owner_user_id = str(task.get("owner_user_id") or task.get("user_id") or task.get("created_by_user_id") or self.legacy_owner())
        owner_username = str(task.get("owner_username") or task.get("username") or task.get("created_by_username") or "")
        full_config = self.storage.load()
        store = self.training_state_store(full_config)
        owner_key = self.normalize_training_owner_key(owner_user_id)
        existing = store.get(owner_key) if isinstance(store.get(owner_key), dict) else {}
        state = {**self.default_training_state(), **dict(existing)}
        for key in (
            "status",
            "progress",
            "note",
            "error",
            "current_epoch",
            "total_epochs",
            "completed_at",
            "stopped_at",
            "cancelled_at",
            "return_code",
            "training_executor",
            "remote_training_status",
            "remote_training_poll_error",
            "training_run_dir",
            "imported_model_path",
            "runpod_job_id",
            "runpod_best_pt_sha256",
        ):
            if key in task:
                state[key] = task.get(key)
        state.update(
            {
                "active_training_task_id": str(task.get("job_id") or task.get("task_id") or job_id),
                "active_training_action": task.get("action") or state.get("active_training_action") or "",
                "selected_accessory_ids": task.get("selected_accessory_ids") or state.get("selected_accessory_ids") or [],
                "sample_count": task.get("sample_count") or state.get("sample_count") or 0,
                "mode": task.get("train_mode") or task.get("mode") or task.get("model_variant") or state.get("mode") or "yolo",
                "epochs": task.get("epochs") or state.get("epochs") or 0,
                "image_size": task.get("image_size") or state.get("image_size") or 0,
                "dataset_id": task.get("dataset_id") or task.get("source_dataset_id") or state.get("dataset_id") or "",
                "owner_user_id": owner_user_id,
                "owner_username": owner_username,
                "updated_at": int(time.time()),
            }
        )
        store[owner_key] = state
        full_config["training_by_user_id"] = store
        current_training = full_config.get("training") if isinstance(full_config.get("training"), dict) else {}
        current_owner_key = self.normalize_training_owner_key(self.access.owner(current_training)) if current_training else ""
        if current_owner_key == owner_key or str(current_training.get("active_training_task_id") or "") == job_id:
            full_config["training"] = state
        self.storage.save(full_config)
        self.sync_pipeline(task)

local_inspection_service/training/datase.parent_source:
"""Dataset manifest projection and ordered, permission-aware filesystem lookup."""
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
import re
from typing import Any, Protocol
from .file_ports import DatasetCatalogFiles

Record = dict[str, Any]


class DatasetItem(Protocol):
    def __call__(self, directory: Path, *, include_samples: bool = True) -> Record | None: ...


class FindDataset(Protocol):
    def __call__(self, dataset_id: str, user: Record | None = None, *,
                 include_samples: bool = False, write: bool = False) -> tuple[Path | None, Record | None]: ...


@dataclass(frozen=True)
class DatasetPaths:
    output: Callable[[], Path]
    resolve: Callable[[], Callable[[Any], Path]]
    roots: Callable[[], list[Path]]
    clean: Callable[[str], str]


@dataclass(frozen=True)
class DatasetAudit:
    fields: Callable[[Record, Path], Record]
    created: Callable[[], Callable[[Record, Path], Any]]
    updated: Callable[[], Callable[[Record, Path], Any]]


@dataclass(frozen=True)
class DatasetAccess:
    visible: Callable[[Record, Record], bool]
    mutable: Callable[[Record, Record], bool]


def clean_training_resource_id(value: str) -> str:
    return re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(value or "")).strip("._")


class DatasetCatalog:
    def __init__(self, paths: DatasetPaths, read: Callable[[Path], Any], audit: DatasetAudit,
                 access: DatasetAccess, item: DatasetItem, *, files: DatasetCatalogFiles):
        self.paths, self.read, self.audit = paths, read, audit
        self.access, self.item = access, item
        if files is None:
            raise TypeError('files is required')
        self.files = files

    def dataset_resource_item(self, dataset_dir, *, include_samples=True):
        if self.files.runtime_provider() is None:
            return self._local_dataset_resource_item(dataset_dir, include_samples=include_samples)
        return self._cos_dataset_resource_item(dataset_dir, include_samples=include_samples)

    def _local_dataset_resource_item(self, dataset_dir: Path, *, include_samples: bool = True) -> dict[str, Any] | None:
        manifest_path = dataset_dir / "manifest.json"
        if not manifest_path.exists():
            return None
        manifest = self.read(manifest_path)
        if not isinstance(manifest, dict):
            return None
        raw_samples = manifest.get("samples") if isinstance(manifest.get("samples"), list) else []
        audit = self.audit.fields(manifest, dataset_dir)
        samples = []
        if include_samples:
            # Per-sample hydration touches the filesystem (resolve + exists + stat fallbacks),
            # so it only runs when the caller actually needs sample payloads.
            for sample in raw_samples:
                if not isinstance(sample, dict):
                    continue
                sample_path = self.paths.resolve()(sample.get("image")) if sample.get("image") else dataset_dir
                sample_copy = dict(sample)
                sample_copy.update(
                    {
                        "created_at": self.audit.created()(sample_copy, sample_path if sample_path.exists() else dataset_dir),
                        "updated_at": self.audit.updated()(sample_copy, sample_path if sample_path.exists() else dataset_dir),
                        "owner_user_id": str(sample_copy.get("owner_user_id") or audit["owner_user_id"]),
                        "owner_username": str(sample_copy.get("owner_username") or audit["owner_username"]),
                    }
                )
                samples.append(sample_copy)
        sample_count = len(samples) if include_samples else len([s for s in raw_samples if isinstance(s, dict)])
        item = {
            "id": dataset_dir.name,
            "kind": "dataset",
            "display_name": manifest.get("display_name") or dataset_dir.name,
            "note": manifest.get("note") or "",
            "path": str(dataset_dir),
            "manifest_path": str(manifest_path),
            "sample_count": sample_count or manifest.get("sample_count") or 0,
            "created_at": audit["created_at"],
            "updated_at": audit["updated_at"],
            "selected_accessory_ids": manifest.get("selected_accessory_ids") or [],
            "background_set_id": manifest.get("background_set_id") or "",
            "owner_user_id": audit["owner_user_id"],
            "owner_username": audit["owner_username"],
            "samples_loaded": bool(include_samples),
        }
        if include_samples:
            item["samples"] = samples
        return item

    def _cos_dataset_resource_item(self, dataset_dir: Path, *, include_samples: bool = True) -> dict[str, Any] | None:
        manifest_path = dataset_dir / "manifest.json"
        if not self.files.is_file(manifest_path):
            return None
        manifest = self.read(manifest_path)
        if not isinstance(manifest, dict):
            return None
        raw_samples = manifest.get("samples") if isinstance(manifest.get("samples"), list) else []
        audit = self.audit.fields(manifest, dataset_dir)
        samples = []
        if include_samples:
            # Per-sample hydration touches the filesystem (resolve + exists + stat fallbacks),
            # so it only runs when the caller actually needs sample payloads.
            for sample in raw_samples:
                if not isinstance(sample, dict):
                    continue
                sample_path = self.paths.resolve()(sample.get("image")) if sample.get("image") else dataset_dir
                sample_copy = dict(sample)
                sample_copy.update(
                    {
                        "created_at": self.audit.created()(sample_copy, sample_path if self.files.exists(sample_path) else dataset_dir),
                        "updated_at": self.audit.updated()(sample_copy, sample_path if self.files.exists(sample_path) else dataset_dir),
                        "owner_user_id": str(sample_copy.get("owner_user_id") or audit["owner_user_id"]),
                        "owner_username": str(sample_copy.get("owner_username") or audit["owner_username"]),
                    }
                )
                samples.append(sample_copy)
        sample_count = len(samples) if include_samples else len([s for s in raw_samples if isinstance(s, dict)])
        item = {
            "id": dataset_dir.name,
            "kind": "dataset",
            "display_name": manifest.get("display_name") or dataset_dir.name,
            "note": manifest.get("note") or "",
            "path": str(dataset_dir),
            "manifest_path": str(manifest_path),
            "sample_count": sample_count or manifest.get("sample_count") or 0,
            "created_at": audit["created_at"],
            "updated_at": audit["updated_at"],
            "selected_accessory_ids": manifest.get("selected_accessory_ids") or [],
            "background_set_id": manifest.get("background_set_id") or "",
            "owner_user_id": audit["owner_user_id"],
            "owner_username": audit["owner_username"],
            "samples_loaded": bool(include_samples),
        }
        if include_samples:
            item["samples"] = samples
        return item

    def training_task_dataset_resource_id(self, task: dict[str, Any]) -> str:
        dataset_dir_value = str(task.get("dataset_dir") or "").strip()
        if not dataset_dir_value:
            return ""
        return self.paths.clean(Path(dataset_dir_value).name)

    def find_dataset_resource(self, dataset_id, user=None, *, include_samples=False, write=False):
        if self.files.runtime_provider() is None:
            return self._local_find_dataset_resource(dataset_id, user, include_samples=include_samples, write=write)
        return self._cos_find_dataset_resource(dataset_id, user, include_samples=include_samples, write=write)

    def _local_find_dataset_resource(self,
        dataset_id: str,
        user: dict[str, Any] | None = None,
        *,
        include_samples: bool = False,
        write: bool = False,
    ) -> tuple[Path | None, dict[str, Any] | None]:
        clean_id = self.paths.clean(dataset_id)
        if not clean_id:
            return None, None
        for root in self.paths.roots():
            candidate_dir = root / clean_id
            if not candidate_dir.exists() or not candidate_dir.is_dir():
                continue
            item = self.item(candidate_dir, include_samples=include_samples)
            if not item:
                continue
            if user:
                allowed = self.access.mutable(item, user) if write else self.access.visible(item, user)
                if not allowed:
                    continue
            return candidate_dir, item
        return None, None

    def _cos_find_dataset_resource(self,
        dataset_id: str,
        user: dict[str, Any] | None = None,
        *,
        include_samples: bool = False,
        write: bool = False,
    ) -> tuple[Path | None, dict[str, Any] | None]:
        clean_id = self.paths.clean(dataset_id)
        if not clean_id:
            return None, None
        for root in self.paths.roots():
            candidate_dir = root / clean_id
            if not self.files.is_dir(candidate_dir):
                continue
            item = self.item(candidate_dir, include_samples=include_samples)
            if not item:
                continue
            if user:
                allowed = self.access.mutable(item, user) if write else self.access.visible(item, user)
                if not allowed:
                    continue
            return candidate_dir, item
        return None, None

    def training_dataset_roots(self):
        if self.files.runtime_provider() is None:
            return self._local_training_dataset_roots()
        return self._cos_training_dataset_roots()

    def _local_training_dataset_roots(self) -> list[Path]:
        roots = [self.paths.output() / "training_datasets"]
        users_root = self.paths.output() / "users"
        if users_root.exists():
            roots.extend(path / "training_datasets" for path in users_root.iterdir() if path.is_dir())
        return roots

    def _cos_training_dataset_roots(self) -> list[Path]:
        roots = [self.paths.output() / "training_datasets"]
        users_root = self.paths.output() / "users"
        roots.extend(path / "training_datasets" for path in self.files.directories(users_root))
        return roots

    def training_run_roots(self):
        if self.files.runtime_provider() is None:
            return self._local_training_run_roots()
        return self._cos_training_run_roots()

    def _local_training_run_roots(self) -> list[Path]:
        roots = [self.paths.output() / "training_runs"]
        users_root = self.paths.output() / "users"
        if users_root.exists():
            roots.extend(path / "training_runs" for path in users_root.iterdir() if path.is_dir())
        return roots

    def _cos_training_run_roots(self) -> list[Path]:
        roots = [self.paths.output() / "training_runs"]
        users_root = self.paths.output() / "users"
        roots.extend(path / "training_runs" for path in self.files.directories(users_root))
        return roots

local_inspection_service/training/resour.parent_source:
"""Training resource aggregation; task listing preserves its lifecycle settlement."""
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Protocol
from .dataset_catalog import DatasetItem
from .file_ports import TrainingResourceFiles

Record = dict[str, Any]


class ListResourceTasks(Protocol):
    def __call__(self, *, user: Record | None, target_user_id: str | None) -> list[Record]: ...


class ResourcePayload(Protocol):
    def __call__(self, *, include_samples: bool = False, user: Record | None = None,
                 target_user_id: str | None = None) -> Record: ...


@dataclass(frozen=True)
class ResourceDatasets:
    roots: Callable[[], list[Path]]
    item: DatasetItem
    task_id: Callable[[Record], str]


@dataclass(frozen=True)
class ResourceRecords:
    tasks: ListResourceTasks
    models: Callable[[], list[Record]]
    ai: Callable[[], list[Record]]


@dataclass(frozen=True)
class ResourceConfiguration:
    load: Callable[[], Record]
    scope: Callable[[], Callable[[Record, Record, str | None], Record]]
    serialize_ai: Callable[[Record, Record], Record]


@dataclass(frozen=True)
class ResourceAccess:
    visible: Callable[[Record, Record, str | None], bool]
    owner_username: Callable[[Record], str]
    legacy_owner: Callable[[], str]
    sanitize: Callable[[Record], Record]


class TrainingResources:
    def __init__(self, datasets: ResourceDatasets, records: ResourceRecords,
                 config: ResourceConfiguration, access: ResourceAccess,
                 resolve: Callable[[], Callable[[Any], Path]], output: Callable[[], Path], *, files: TrainingResourceFiles):
        self.datasets, self.records, self.config = datasets, records, config
        self.access, self.resolve, self.output = access, resolve, output
        if files is None:
            raise TypeError('files is required')
        self.files = files

    def training_resources_payload(self, *, include_samples=False, user=None, target_user_id=None):
        if self.files.runtime_provider() is None:
            return self._local_training_resources_payload(include_samples=include_samples, user=user, target_user_id=target_user_id)
        return self._cos_training_resources_payload(include_samples=include_samples, user=user, target_user_id=target_user_id)

    def _local_training_resources_payload(self,
        *,
        include_samples: bool = False,
        user: dict[str, Any] | None = None,
        target_user_id: str | None = None,
    ) -> dict[str, Any]:
        datasets = []
        for datasets_dir in self.datasets.roots():
            if not datasets_dir.exists():
                continue
            for dataset_dir in sorted([p for p in datasets_dir.iterdir() if p.is_dir()], key=lambda p: p.stat().st_mtime, reverse=True):
                item = self.datasets.item(dataset_dir, include_samples=include_samples)
                if item:
                    if user and not self.access.visible(item, user, target_user_id):
                        continue
                    datasets.append(item)
        task_items = self.records.tasks(user=user, target_user_id=target_user_id)
        dataset_ids = {item["id"] for item in datasets}
        for task in task_items:
            dataset_dir_value = task.get("dataset_dir")
            if task.get("action") not in {"generate_samples", "train_model"} or not dataset_dir_value:
                continue
            if str(task.get("dataset_status") or "") == "deleted":
                continue
            dataset_id = self.datasets.task_id(task)
            if not dataset_id:
                continue
            if dataset_id in dataset_ids:
                continue
            datasets.append(
                {
                    "id": dataset_id,
                    "kind": "dataset",
                    "display_name": task.get("label") or dataset_id,
                    "note": "样本文件缺失或已被删除；这是任务记录中的历史资源。",
                    "path": str(dataset_dir_value),
                    "manifest_path": str(task.get("manifest_path") or ""),
                    "sample_count": int(task.get("completed_samples") or task.get("sample_count") or 0),
                    "created_at": int(task.get("created_at") or 0),
                    "selected_accessory_ids": task.get("selected_accessory_ids") or [],
                    "background_set_id": task.get("background_set_id") or "",
                    "owner_user_id": str(task.get("owner_user_id") or ""),
                    "owner_username": str(task.get("owner_username") or ""),
                    "samples": [] if include_samples else None,
                    "samples_loaded": bool(include_samples),
                    "missing_files": True,
                }
            )
            dataset_ids.add(dataset_id)
        specs = self.records.models()
        models = []
        for spec in specs:
            if user and not self.access.visible(spec, user, target_user_id):
                continue
            model_path = Path(spec["path"])
            run_id = str(spec["run_id"])
            run_dir = self.resolve()(spec.get("run_dir") or (self.output() / "training_runs" / run_id))
            timestamp_path = model_path if model_path.exists() else run_dir
            models.append(
                {
                    "id": spec["id"],
                    "run_id": run_id,
                    "task_id": spec["task_id"],
                    "pipeline_task_id": spec.get("pipeline_task_id") or "",
                    "pipeline_task_name": spec.get("pipeline_task_name") or "",
                    "variant": spec["variant"],
                    "kind": "model",
                    "label": spec["label"],
                    "note": spec.get("note") or "",
                    "path": str(model_path),
                    "exists": model_path.exists(),
                    "uses_ocr": bool(spec.get("uses_ocr", False)),
                    "created_at": int(spec.get("created_at") or (timestamp_path.stat().st_mtime if timestamp_path.exists() else 0)),
                    "updated_at": int(spec.get("updated_at") or spec.get("created_at") or (timestamp_path.stat().st_mtime if timestamp_path.exists() else 0)),
                    "accessory_names": spec.get("accessory_names") or [],
                    "selected_accessory_ids": spec.get("selected_accessory_ids") or [],
                    "owner_user_id": str(spec.get("owner_user_id") or self.access.legacy_owner()),
                    "owner_username": str(spec.get("owner_username") or self.access.owner_username(spec)),
                }
            )
        completed_tasks = []
        for task in task_items:
            if task.get("action") not in {"generate_samples", "train_model"}:
                continue
            task_id = str(task.get("job_id") or "")
            completed_tasks.append(
                {
                    **task,
                    "dataset": next((item for item in datasets if item["id"] == task_id), None),
                    "models": [item for item in models if item.get("task_id") == task_id],
                }
            )
        config = self.config.scope()(self.config.load(), user, target_user_id) if user else self.config.load()
        # sync_ready_pipeline_ai_detection_tasks is a permanent no-op, so the former
        # load-and-maybe-save of pipeline tasks here was removed from this read path.
        ai_detection_tasks = [
            {**self.config.serialize_ai(task, config), "kind": "ai_detection_task", "task_type": "ai_detection"}
            for task in self.records.ai()
            if not user or self.access.visible(task, user, target_user_id)
        ]
        return self.access.sanitize({
            "datasets": datasets,
            "models": models,
            "tasks": task_items,
            "training_tasks": completed_tasks,
            "ai_detection_tasks": ai_detection_tasks,
        })

    def _cos_training_resources_payload(self,
        *,
        include_samples: bool = False,
        user: dict[str, Any] | None = None,
        target_user_id: str | None = None,
    ) -> dict[str, Any]:
        datasets = []
        for datasets_dir in self.datasets.roots():
            indexed = self.files.runtime(datasets_dir) is not None
            order = (lambda p: p.name) if indexed else (lambda p: p.stat().st_mtime)
            for dataset_dir in sorted(self.files.directories(datasets_dir), key=order, reverse=True):
                item = self.datasets.item(dataset_dir, include_samples=include_samples)
                if item:
                    if user and not self.access.visible(item, user, target_user_id):
                        continue
                    datasets.append(item)
        task_items = self.records.tasks(user=user, target_user_id=target_user_id)
        dataset_ids = {item["id"] for item in datasets}
        for task in task_items:
            dataset_dir_value = task.get("dataset_dir")
            if task.get("action") not in {"generate_samples", "train_model"} or not dataset_dir_value:
                continue
            if str(task.get("dataset_status") or "") == "deleted":
                continue
            dataset_id = self.datasets.task_id(task)
            if not dataset_id:
                continue
            if dataset_id in dataset_ids:
                continue
            datasets.append(
                {
                    "id": dataset_id,
                    "kind": "dataset",
                    "display_name": task.get("label") or dataset_id,
                    "note": "样本文件缺失或已被删除；这是任务记录中的历史资源。",
                    "path": str(dataset_dir_value),
                    "manifest_path": str(task.get("manifest_path") or ""),
                    "sample_count": int(task.get("completed_samples") or task.get("sample_count") or 0),
                    "created_at": int(task.get("created_at") or 0),
                    "selected_accessory_ids": task.get("selected_accessory_ids") or [],
                    "background_set_id": task.get("background_set_id") or "",
                    "owner_user_id": str(task.get("owner_user_id") or ""),
                    "owner_username": str(task.get("owner_username") or ""),
                    "samples": [] if include_samples else None,
                    "samples_loaded": bool(include_samples),
                    "missing_files": True,
                }
            )
            dataset_ids.add(dataset_id)
        specs = self.records.models()
        models = []
        for spec in specs:
            if user and not self.access.visible(spec, user, target_user_id):
                continue
            model_path = Path(spec["path"])
            run_id = str(spec["run_id"])
            run_dir = self.resolve()(spec.get("run_dir") or (self.output() / "training_runs" / run_id))
            timestamp_path = model_path if model_path.exists() else run_dir
            models.append(
                {
                    "id": spec["id"],
                    "run_id": run_id,
                    "task_id": spec["task_id"],
                    "pipeline_task_id": spec.get("pipeline_task_id") or "",
                    "pipeline_task_name": spec.get("pipeline_task_name") or "",
                    "variant": spec["variant"],
                    "kind": "model",
                    "label": spec["label"],
                    "note": spec.get("note") or "",
                    "path": str(model_path),
                    "exists": self.files.is_file(model_path),
                    "uses_ocr": bool(spec.get("uses_ocr", False)),
                    "created_at": int(spec.get("created_at") or (timestamp_path.stat().st_mtime if timestamp_path.exists() else 0)),
                    "updated_at": int(spec.get("updated_at") or spec.get("created_at") or (timestamp_path.stat().st_mtime if timestamp_path.exists() else 0)),
                    "accessory_names": spec.get("accessory_names") or [],
                    "selected_accessory_ids": spec.get("selected_accessory_ids") or [],
                    "owner_user_id": str(spec.get("owner_user_id") or self.access.legacy_owner()),
                    "owner_username": str(spec.get("owner_username") or self.access.owner_username(spec)),
                }
            )
        completed_tasks = []
        for task in task_items:
            if task.get("action") not in {"generate_samples", "train_model"}:
                continue
            task_id = str(task.get("job_id") or "")
            completed_tasks.append(
                {
                    **task,
                    "dataset": next((item for item in datasets if item["id"] == task_id), None),
                    "models": [item for item in models if item.get("task_id") == task_id],
                }
            )
        config = self.config.scope()(self.config.load(), user, target_user_id) if user else self.config.load()
        # sync_ready_pipeline_ai_detection_tasks is a permanent no-op, so the former
        # load-and-maybe-save of pipeline tasks here was removed from this read path.
        ai_detection_tasks = [
            {**self.config.serialize_ai(task, config), "kind": "ai_detection_task", "task_type": "ai_detection"}
            for task in self.records.ai()
            if not user or self.access.visible(task, user, target_user_id)
        ]
        return self.access.sanitize({
            "datasets": datasets,
            "models": models,
            "tasks": task_items,
            "training_tasks": completed_tasks,
            "ai_detection_tasks": ai_detection_tasks,
        })

